/**\n * Reusable Jetpack Compose Components for IPTV App\n * Pre-built components that match the web design system\n * Use these as building blocks for your Android TV screens\n */\n\npackage com.example.iptvapp.ui.components\n\nimport androidx.compose.foundation.background\nimport androidx.compose.foundation.border\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.itemsIndexed\nimport androidx.compose.foundation.shape.RoundedCornerShape\nimport androidx.compose.material3.Icon\nimport androidx.compose.material3.Text\nimport androidx.compose.runtime.Composable\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.layout.ContentScale\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.text.style.TextOverflow\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.unit.sp\nimport coil.compose.AsyncImage\nimport com.example.iptvapp.ui.theme.*\n\n// ==================== CHANNEL CARD COMPONENT ====================\n/**\n * Channel Card - Displays TV channel with logo, views, and quality badges\n * Optimized for Android TV with large touch targets and focus indicators\n */\n@Composable\nfun ChannelCard(\n    show: Show,\n    isFocused: Boolean = false,\n    onSelect: (Show) -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .fillMaxWidth()\n            .height(144.dp)\n            .background(\n                color = if (isFocused) Slate700 else Slate800,\n                shape = RoundedCornerShape(16.dp)\n            )\n            .border(\n                width = if (isFocused) 4.dp else 2.dp,\n                color = if (isFocused) AccentYellow else Border,\n                shape = RoundedCornerShape(16.dp)\n            )\n            .clickable { onSelect(show) }\n            .padding(24.dp)\n    ) {\n        Row(\n            modifier = Modifier.fillMaxSize(),\n            horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            // Left Section - Icon + Info\n            Row(\n                modifier = Modifier.weight(1f),\n                horizontalArrangement = Arrangement.spacedBy(24.dp),\n                verticalAlignment = Alignment.CenterVertically\n            ) {\n                Text(\n                    text = \"📺\",\n                    fontSize = 56.sp,\n                    modifier = Modifier.size(64.dp)\n                )\n                Column(\n                    modifier = Modifier\n                        .weight(1f)\n                        .fillMaxHeight(),\n                    verticalArrangement = Arrangement.Center\n                ) {\n                    Text(\n                        text = show.name,\n                        fontSize = 22.sp,\n                        fontWeight = FontWeight.Bold,\n                        color = Foreground,\n                        maxLines = 1,\n                        overflow = TextOverflow.Ellipsis\n                    )\n                    Text(\n                        text = \"${show.views} Views\",\n                        fontSize = 16.sp,\n                        color = Slate400,\n                        modifier = Modifier.padding(top = 4.dp)\n                    )\n                }\n            }\n\n            // Right Section - Badges + Star\n            Row(\n                horizontalArrangement = Arrangement.spacedBy(12.dp),\n                verticalAlignment = Alignment.CenterVertically\n            ) {\n                // Quality Badges\n                show.quality.forEach { quality ->\n                    QualityBadge(quality)\n                }\n\n                // Favorite Star\n                if (show.favorite == true) {\n                    Text(\n                        text = \"⭐\",\n                        fontSize = 28.sp,\n                        modifier = Modifier.size(32.dp)\n                    )\n                }\n            }\n        }\n    }\n}\n\n// ==================== QUALITY BADGE COMPONENT ====================\n/**\n * Quality Badge - Shows video quality (4K, HD, EPG, $)\n */\n@Composable\nfun QualityBadge(\n    quality: String,\n    modifier: Modifier = Modifier\n) {\n    val (backgroundColor, textColor) = getQualityBadgeColors(quality)\n\n    Box(\n        modifier = modifier\n            .background(\n                color = backgroundColor,\n                shape = RoundedCornerShape(8.dp)\n            )\n            .padding(horizontal = 12.dp, vertical = 8.dp),\n        contentAlignment = Alignment.Center\n    ) {\n        Text(\n            text = quality,\n            fontSize = 14.sp,\n            fontWeight = FontWeight.Bold,\n            color = textColor\n        )\n    }\n}\n\n// ==================== COUNTRY CARD COMPONENT ====================\n/**\n * Country Card - Sidebar button showing country flag and channel count\n */\n@Composable\nfun CountryCard(\n    country: Country,\n    isSelected: Boolean = false,\n    isFocused: Boolean = false,\n    onSelect: (String) -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .size(width = 180.dp, height = 200.dp)\n            .background(\n                color = when {\n                    isSelected -> Color(0xFF3B52A0) // Blue gradient effect\n                    isFocused -> Slate700\n                    else -> Slate800\n                },\n                shape = RoundedCornerShape(12.dp)\n            )\n            .border(\n                width = if (isFocused) 4.dp else if (isSelected) 2.dp else 1.dp,\n                color = when {\n                    isFocused -> AccentYellow\n                    isSelected -> AccentBlue\n                    else -> Border\n                },\n                shape = RoundedCornerShape(12.dp)\n            )\n            .clickable { onSelect(country.id) }\n            .padding(24.dp),\n        contentAlignment = Alignment.Center\n    ) {\n        Column(\n            horizontalAlignment = Alignment.CenterHorizontally,\n            verticalArrangement = Arrangement.Center\n        ) {\n            Text(\n                text = country.flag,\n                fontSize = 56.sp,\n                modifier = Modifier.padding(bottom = 12.dp)\n            )\n            Text(\n                text = country.name,\n                fontSize = 18.sp,\n                fontWeight = FontWeight.Bold,\n                color = Foreground\n            )\n            Text(\n                text = \"${country.channels} channels\",\n                fontSize = 14.sp,\n                color = Slate400,\n                modifier = Modifier.padding(top = 8.dp)\n            )\n        }\n    }\n}\n\n// ==================== SETTINGS ITEM COMPONENT ====================\n/**\n * Settings Item - Configuration option with toggle or selector\n */\n@Composable\nfun SettingsItem(\n    label: String,\n    value: String,\n    icon: @Composable () -> Unit = {},\n    isFocused: Boolean = false,\n    options: List<String> = emptyList(),\n    onSelect: (String) -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .fillMaxWidth()\n            .background(\n                color = if (isFocused) Slate700 else Slate800,\n                shape = RoundedCornerShape(16.dp)\n            )\n            .border(\n                width = if (isFocused) 4.dp else 2.dp,\n                color = if (isFocused) AccentYellow else Border,\n                shape = RoundedCornerShape(16.dp)\n            )\n            .padding(24.dp)\n    ) {\n        Column {\n            Row(\n                modifier = Modifier\n                    .fillMaxWidth()\n                    .padding(bottom = if (isFocused && options.isNotEmpty()) 24.dp else 0.dp),\n                horizontalArrangement = Arrangement.SpaceBetween,\n                verticalAlignment = Alignment.CenterVertically\n            ) {\n                Row(\n                    modifier = Modifier.weight(1f),\n                    horizontalArrangement = Arrangement.spacedBy(24.dp),\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    Box(\n                        modifier = Modifier\n                            .size(56.dp)\n                            .background(\n                                color = Slate700,\n                                shape = RoundedCornerShape(12.dp)\n                            ),\n                        contentAlignment = Alignment.Center\n                    ) {\n                        icon()\n                    }\n                    Column {\n                        Text(\n                            text = label,\n                            fontSize = 22.sp,\n                            fontWeight = FontWeight.Bold,\n                            color = Foreground\n                        )\n                        Text(\n                            text = value,\n                            fontSize = 16.sp,\n                            color = Slate400,\n                            modifier = Modifier.padding(top = 8.dp)\n                        )\n                    }\n                }\n                Text(\">\", fontSize = 28.sp, color = Slate500)\n            }\n\n            // Show options when focused\n            if (isFocused && options.isNotEmpty()) {\n                Divider(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .height(1.dp)\n                        .background(Slate700)\n                )\n                Row(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .padding(top = 16.dp),\n                    horizontalArrangement = Arrangement.spacedBy(12.dp),\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    options.forEach { option ->\n                        Box(\n                            modifier = Modifier\n                                .background(\n                                    color = if (option == value) AccentBlue else Slate700,\n                                    shape = RoundedCornerShape(8.dp)\n                                )\n                                .border(\n                                    width = if (option == value) 2.dp else 1.dp,\n                                    color = if (option == value) AccentBlue else Border,\n                                    shape = RoundedCornerShape(8.dp)\n                                )\n                                .clickable { onSelect(option) }\n                                .padding(horizontal = 16.dp, vertical = 12.dp)\n                        ) {\n                            Text(\n                                text = option,\n                                fontSize = 14.sp,\n                                fontWeight = FontWeight.Bold,\n                                color = if (option == value) White else Slate200\n                            )\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n\n// ==================== HEADER COMPONENT ====================\n/**\n * Page Header - Title with icon and description\n */\n@Composable\nfun PageHeader(\n    title: String,\n    subtitle: String = \"\",\n    icon: @Composable () -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Column(\n        modifier = modifier\n            .fillMaxWidth()\n            .background(Slate900)\n            .padding(32.dp),\n        verticalArrangement = Arrangement.spacedBy(8.dp)\n    ) {\n        Row(\n            horizontalArrangement = Arrangement.spacedBy(16.dp),\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            icon()\n            Text(\n                text = title,\n                fontSize = 36.sp,\n                fontWeight = FontWeight.Bold,\n                color = Foreground\n            )\n        }\n        if (subtitle.isNotEmpty()) {\n            Text(\n                text = subtitle,\n                fontSize = 16.sp,\n                color = Slate400,\n                modifier = Modifier.padding(start = 72.dp)\n            )\n        }\n    }\n}\n\n// ==================== SEARCH INPUT COMPONENT ====================\n/**\n * Search Input - TV-optimized text input field\n */\n@Composable\nfun SearchInput(\n    value: String,\n    onValueChange: (String) -> Unit,\n    placeholder: String = \"\",\n    isFocused: Boolean = false,\n    onClear: () -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .fillMaxWidth()\n            .background(\n                color = if (isFocused) Slate700 else Slate800,\n                shape = RoundedCornerShape(12.dp)\n            )\n            .border(\n                width = if (isFocused) 4.dp else 2.dp,\n                color = if (isFocused) AccentYellow else Border,\n                shape = RoundedCornerShape(12.dp)\n            )\n            .padding(16.dp)\n    ) {\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .height(56.dp),\n            horizontalArrangement = Arrangement.spacedBy(16.dp),\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            Text(\"🔍\", fontSize = 24.sp)\n            androidx.compose.material3.TextField(\n                value = value,\n                onValueChange = onValueChange,\n                modifier = Modifier\n                    .weight(1f)\n                    .background(Color.Transparent),\n                singleLine = true,\n                textStyle = androidx.compose.ui.text.TextStyle(\n                    fontSize = 20.sp,\n                    color = Foreground\n                ),\n                placeholder = {\n                    Text(\n                        text = placeholder,\n                        color = Slate500,\n                        fontSize = 20.sp\n                    )\n                }\n            )\n            if (value.isNotEmpty()) {\n                Text(\n                    text = \"✕\",\n                    fontSize = 20.sp,\n                    color = Slate500,\n                    modifier = Modifier.clickable { onClear() }\n                )\n            }\n        }\n    }\n}\n\n// ==================== FILTER CHIP COMPONENT ====================\n/**\n * Filter Chip - Selection button for filtering\n */\n@Composable\nfun FilterChip(\n    label: String,\n    icon: String = \"\",\n    isSelected: Boolean = false,\n    onClick: () -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .background(\n                color = if (isSelected) AccentBlue else Slate800,\n                shape = RoundedCornerShape(8.dp)\n            )\n            .border(\n                width = if (isSelected) 2.dp else 1.dp,\n                color = if (isSelected) AccentBlue else Border,\n                shape = RoundedCornerShape(8.dp)\n            )\n            .clickable { onClick() }\n            .padding(horizontal = 16.dp, vertical = 12.dp)\n    ) {\n        Row(\n            horizontalArrangement = Arrangement.spacedBy(8.dp),\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            if (icon.isNotEmpty()) {\n                Text(text = icon, fontSize = 20.sp)\n            }\n            Text(\n                text = label,\n                fontSize = 14.sp,\n                fontWeight = FontWeight.Bold,\n                color = if (isSelected) White else Slate200\n            )\n        }\n    }\n}\n\n// ==================== BUTTON COMPONENTS ====================\n/**\n * TV-Optimized Button - Large touch target\n */\n@Composable\nfun TVButton(\n    label: String = \"\",\n    onClick: () -> Unit = {},\n    isFocused: Boolean = false,\n    modifier: Modifier = Modifier\n) {\n    Box(\n        modifier = modifier\n            .size(64.dp)\n            .background(\n                color = if (isFocused) AccentBlue else Slate700,\n                shape = RoundedCornerShape(32.dp)\n            )\n            .border(\n                width = if (isFocused) 2.dp else 1.dp,\n                color = if (isFocused) AccentBlue else Border,\n                shape = RoundedCornerShape(32.dp)\n            )\n            .clickable { onClick() },\n        contentAlignment = Alignment.Center\n    ) {\n        if (label.isNotEmpty()) {\n            Text(\n                text = label,\n                fontSize = 24.sp,\n                fontWeight = FontWeight.Bold,\n                color = White\n            )\n        }\n    }\n}\n\n// ==================== DIVIDER COMPONENT ====================\n@Composable\nfun Divider(\n    modifier: Modifier = Modifier,\n    color: Color = Border,\n    thickness: dp = 1.dp\n) {\n    Box(\n        modifier = modifier\n            .height(thickness)\n            .background(color)\n    )\n}\n\n// ==================== LAZY CHANNEL LIST ====================\n/**\n * Reusable lazy column for channels list with focus management\n */\n@Composable\nfun ChannelList(\n    shows: List<Show>,\n    focusedIndex: Int,\n    onSelect: (Show) -> Unit = {},\n    modifier: Modifier = Modifier\n) {\n    LazyColumn(\n        modifier = modifier\n            .fillMaxWidth()\n            .padding(16.dp),\n        verticalArrangement = Arrangement.spacedBy(16.dp)\n    ) {\n        itemsIndexed(shows) { index, show ->\n            ChannelCard(\n                show = show,\n                isFocused = focusedIndex == index,\n                onSelect = onSelect\n            )\n        }\n    }\n}\n"
}
